const $=(s)=>document.querySelector(s);
const icon=(n=0)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${['<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4M6 6h12"/>','<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20"/>','<path d="M21 11a9 9 0 0 1-13 8l-5 2 1-6a9 9 0 1 1 17-4Z"/><path d="M8 11h.01M12 11h.01M16 11h.01"/>','<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>','<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>','<path d="m16 3 5 5L9 20l-6 1 1-6Z"/>'][n%6]}</svg>`;
const logo=`<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M3 28 14 6h9L12 28Z" fill="#8b5cf6"/><path d="m19 15 7-9 8 22H22l-3-7-5 7H8Z" fill="#17121f"/><path d="m22 21 3 7h-7Z" fill="#c4b5fd"/></svg><span>Align Craft<span class="accent">.</span></span>`;
const services=['Mobile App Development','SaaS & Web App Development','AI Solutions & WhatsApp Agents','Backend & API Development','Website Development','UI/UX & Product Design','DevOps & Cloud Infrastructure','Cybersecurity','Technical Compliance Support','Software Project Management','MVP Development'];
const descriptions=['Thoughtful iOS and Android experiences, from first prototype to the app stores.','Multi-user platforms, dashboards and SaaS products built around real workflows.','Useful automation, conversational experiences and connected business systems.','Reliable application logic, integrations and infrastructure that hold everything together.','Fast, expressive websites that turn a clear story into a compelling experience.'];
const projects=[['Forma','SaaS · Product design','A calmer way to manage your everyday work.','Less busywork.\nMore flow.',''],['Gather','Commerce · Web development','A considered digital storefront for everyday essentials.','Good things,\nbrought together.','coral'],['Mono','Fintech · Mobile app','A simple, confident approach to your money.','Your money.\nYour momentum.','night'],['Fieldwork','Operations · Platform','Connecting the details, from the field to the office.','Everything\nin its place.','mint'],['Petal','Lifestyle · E-commerce','Making room for a little more green.','Small changes.\nGrowing impact.','lime'],['Formly','No-code · SaaS','From the first question to a better decision.','Good questions.\nBetter answers.','blue']];
const btns=(primary='Book a call')=>`<div class="buttons"><button class="btn primary" data-contact>${primary} <span>↗</span></button><a class="btn" href="/#work">View our work <span>↗</span></a></div>`;
function navGroup(title,links){return `<div class="navgroup"><button aria-expanded="false">${title}</button><div class="dropdown">${links.map(([t,url,i])=>`<a href="${url}">${i!==undefined?icon(i):''}${t}</a>`).join('')}</div></div>`}
function header(){return `<header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Align Craft home">${logo}</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button><nav class="nav" aria-label="Main navigation">${navGroup('Services',services.map((s,i)=>[s,'/#services',i]))}${navGroup('Work',[['All work','/#work'],...projects.slice(0,4).map(p=>[p[0],'/#work']),['Our approach','/#process']])}<a href="/pricing" ${location.pathname.includes('pricing')?'class="active"':''}>Pricing</a>${navGroup('About',[['Our studio','/about'],['How we work','/about#standards'],['Delivery team','/about#team']])}${navGroup('Resources',[['Insights','/#insights'],['FAQs','/#faq'],['Start a project','/#contact']])}</nav></div></header>`}
function footer(){return `<section class="dark prefooter" id="contact"><span class="eyebrow">Your next chapter starts here</span><h2>Tell us what you are building.<br><strong>We’ll help define the next phase.</strong></h2><p>A new idea, a tricky product problem, or a better way forward. Let’s make it tangible.</p>${btns()}</section><footer class="dark footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="/">${logo}</a><p>Product, design and engineering.<br>Aligned from the first conversation.</p><button class="btn primary" data-contact>Let’s build something ↗</button><p style="margin-top:18px">An independent digital studio.<br>Built for ambitious ideas.</p></div>${[['Services',...services.slice(0,5)],['Company','About us','How we work','Start a project'],['Resources','Selected work','Insights','FAQs','Pricing']].map((group,i)=>`<div class="footer-links"><div class="footer-title">${group[0]}</div>${group.slice(1).map((s,j)=>`<a href="${i===0?'/#services':i===1?['/about','/#process','/#contact'][j]:['/#work','/#insights','/#faq','/pricing'][j]}">${s}</a>`).join('')}</div>`).join('')}<div class="footer-arch"><div class="arch" role="img" aria-label="An illuminated lavender archway"></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Align Craft. Thoughtfully built.</span><span>Clarity. Craft. Forward.</span></div></div></footer>`}
const faqData=[['Can you help us shape an early-stage idea?','Yes. We start with the problem, the people using the product and what success should look like. Discovery turns that into a practical scope, a delivery plan and a quote.'],['Do you handle design and engineering together?','Our approach connects product strategy, interface design and engineering in one delivery process. The team and responsibilities are agreed before your phase starts.'],['How is a project priced?','We quote a defined phase after discovery. The proposal describes the outcome, scope, timeline, assumptions and payment milestones. See our pricing page for the full approach.'],['How much does a project cost?','There is no one-size-fits-all price. Platforms, workflow complexity, integrations and your starting point all affect the work. A short conversation helps us propose a sensible first phase.'],['What happens after launch?','Every phase includes an agreed handover. Ongoing maintenance, support and the next round of improvements can be scoped as a separate engagement.']];
const pricingFaq=[['Do I need to know my budget before contacting you?','A budget range is helpful, but a clear product problem is a good starting point. We can discuss priorities and shape a realistic first phase together.'],['Is the range the final quote?','No. Timelines describe typical planning windows. Your written proposal confirms the exact scope, fee, timeline and acceptance criteria after discovery.'],['How are payments structured?','Payment milestones are agreed in your proposal before work begins. They are tied to the specific delivery phase and its commercial terms.'],['Do third-party fees come out of the development fee?','Hosting, paid APIs, app store accounts and other external services are separate unless the proposal explicitly includes them.'],['What happens when I request new features after scope is signed?','We assess the effect on price and timeline, then agree a scope change or move the feature into a later phase.'],['Is maintenance included forever?','No. The handover and any contracted warranty are defined in the proposal. Continuing support can be scoped separately.']];
const faq=(data=faqData)=>data.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
function mockup(p,i){return `<div class="mockup ${p[4]}"><div class="mock-copy"><small>${p[0].toUpperCase()} / CONCEPT ${String(i+1).padStart(2,'0')}</small>${p[3].replace('\n','<br>')}</div>${i===2?`<div class="phone"><div class="phone-screen">mono ↗<strong>Make room<br>for more.</strong><div style="font-size:22px">₦ 240,000</div><i></i><i></i><i></i></div></div>`:`<div class="browser"><div class="browser-bar"><i></i><i></i><i></i></div><div class="browser-content"><span>${p[0]} ↗</span><strong style="margin-top:16px">${p[3].replace('\n','<br>')}</strong><span class="mini-btn">Explore ${p[0]} ↗</span><div class="mini-grid"><i></i><i></i><i></i></div></div></div>`}</div>`}
function work(){return `<section class="section tint" id="work"><div class="wrap"><span class="eyebrow">✳ Selected explorations</span><div class="section-head"><h2>Good ideas deserve<br><strong>exceptional execution.</strong></h2><p>A glimpse of what we can build together.<br>Original concept projects, crafted to show our approach.</p></div><div class="work-grid">${projects.map((p,i)=>`<a class="project" href="#project-${i}" data-project="${i}">${mockup(p,i)}<div class="project-meta"><h3>${p[0]} <span style="font-weight:400">↗</span></h3><span class="tag">${p[1]}</span></div><p>${p[2]}</p></a>`).join('')}</div><div class="after-grid"><button class="btn" data-contact>Have a project in mind? <span>↗</span></button></div></div></section>`}
function home(){return `<section class="hero grid-bg"><span class="eyebrow">Plan. Build. Launch.</span><h1>A design & development team<strong>for ambitious founders.</strong></h1><p>From the first spark to the product people use.<br>We bring product thinking, considered design and dependable engineering into one aligned team.</p>${btns()}<div class="hero-art"><img src="/assets/creation.png" alt="Two classical marble hands reaching toward a lavender spark" fetchpriority="high"><span class="art-label">WHERE AMBITION MEETS CRAFT.</span></div></section><section class="dark metrics"><div class="wrap"><p class="metrics-intro">Big ideas need more than a beautiful interface.<br>They need a team that connects every part.</p><div class="metrics-grid">${[['01','Aligned team'],['05','Delivery phases'],['End to end','From idea to handover'],['100<span class="accent">%</span>','Focused on the outcome']].map(([v,t])=>`<div class="metric"><strong>${v}</strong><small>${t}</small></div>`).join('')}</div></div></section>${work()}<section class="section" id="services"><div class="wrap"><div class="split"><div class="intro"><span class="eyebrow">What we build</span><h2>One team for<br>product, design<br><strong>and engineering.</strong></h2><p>Start with the outcome you need. We connect the product, design and engineering work to get you there.</p><a class="btn" href="/pricing">Explore our services ↗</a></div><div class="service-grid">${services.slice(0,4).map((s,i)=>`<article class="service-card">${icon(i)}<h3>${s}</h3><p>${descriptions[i]}</p><a href="/pricing#phases">Explore service ↗</a></article>`).join('')}</div></div><div class="tags">${services.slice(4).map(s=>`<a class="tag" href="/pricing#phases">${s}</a>`).join('')}</div></div></section><section class="section tint"><div class="wrap"><span class="eyebrow">Tools are a means. Outcomes are the point.</span><h2>A stack for products that<br>need to <strong>launch and last.</strong></h2><p>Modern tools, chosen for the job. No unnecessary complexity.</p><div class="stack">${[['⚛','React'],['N↗','Next.js'],['TS','TypeScript'],['⬡','Node.js'],['Py','Python'],['aws','AWS'],['▦','Docker'],['Pg','PostgreSQL'],['F','Figma'],['◎','React Native'],['◈','Redis'],['git','Git'],['◇','Cloudflare'],['≋','Tailwind CSS'],['✳','OpenAI'],['⌘','GitHub']].map(([m,n])=>`<div><strong>${m}</strong><small>${n}</small></div>`).join('')}</div></div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Less handoff. More ownership.</span><h2>One project plan for product,<br><strong>design and engineering.</strong></h2><p>Shared context. Clear decisions. A team accountable for what ships.</p><div class="team-banner"><img src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1600&q=85" alt="A team collaborating around a table" loading="lazy"><h2>Named owners.<br>Clear handover.</h2></div></div></section><section class="section" id="process"><div class="wrap"><span class="eyebrow">How we work</span><h2>Five phases from<br>problem to <strong>handover.</strong></h2><p>You know what’s next, who owns it and what happens now.</p><div class="steps">${[['Discovery','Define the problem, priorities and scope.'],['Design','Make the experience clear before the build.'],['Build','Turn approved direction into working software.'],['Test','Check the details, the edge cases and the release.'],['Launch','Ship with documentation and a clear handover.']].map(([t,d],i)=>`<div class="step"><span>0${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></section><section class="section tint"><div class="wrap"><div class="split"><div><span class="eyebrow">Built into the relationship</span><h2>Good work starts<br>with <strong>good alignment.</strong></h2></div><div class="hairline-grid">${[['A clear starting point','Scope, ownership and acceptance criteria before we build.'],['A visible process','Regular progress updates and decisions you can follow.'],['Room for honest conversations','Tradeoffs explained clearly, with no surprises buried in the details.'],['A useful finish','Source, documentation and knowledge transferred to your team.']].map(([t,p])=>`<div class="hairline-cell"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></div></section><section class="section" id="faq"><div class="wrap"><div class="faq-wrap"><span class="eyebrow">A little clarity</span><h2>Before we talk,<br><strong>quick answers.</strong></h2>${faq()}<a class="btn after-grid" href="/pricing">More about pricing ↗</a></div></div></section><section class="section tint" id="insights"><div class="wrap"><span class="eyebrow">The studio notebook</span><div class="section-head"><h2>For people making<br><strong>the product decisions.</strong></h2></div><div class="insights">${[['01 /','Strategy','Your first release doesn’t need every feature.'],['{ }','Engineering','A good handover starts before the first line of code.'],['↗','Delivery','How to turn a big idea into a useful first phase.']].map(([art,cat,t],i)=>`<a class="article" href="#article-${i}" data-article="${i}"><div class="article-art">${art}</div><div class="article-content"><span class="eyebrow">${cat} · 3 min read</span><h3>${t}</h3><p>Practical thinking for a clearer path from idea to launch.</p><span class="text-link">Read the note ↗</span></div></a>`).join('')}</div></div></section>`}
const scale=`<svg viewBox="0 0 300 320" fill="none" aria-label="A classical balance scale"><defs><linearGradient id="metal" x1="90" y1="0" x2="230" y2="250" gradientUnits="userSpaceOnUse"><stop stop-color="#ddd6e8"/><stop offset=".4" stop-color="#655874"/><stop offset=".55" stop-color="#c2aecf"/><stop offset="1" stop-color="#31283d"/></linearGradient></defs><circle cx="150" cy="145" r="125" fill="#8b5cf6" opacity=".06"/><path d="m150 40 0 223M55 85q95 30 190 0" stroke="url(#metal)" stroke-width="12"/><circle cx="150" cy="35" r="12" fill="url(#metal)"/><path d="m55 88-35 100m35-100 35 100m155-100-35 100m35-100 35 100" stroke="#62536e" stroke-width="2"/><path d="M15 188q40 47 80 0ZM205 188q40 47 80 0Z" fill="url(#metal)"/><path d="m137 92-5 167h36l-5-167Z" fill="url(#metal)"/><path d="m132 259-24 21h84l-24-21ZM100 282h100l12 16H88Z" fill="url(#metal)"/><circle cx="150" cy="85" r="8" fill="#8b5cf6"/></svg>`;
const torch=`<svg viewBox="0 0 300 320" fill="none" aria-label="A classical torch with a lavender flame"><defs><linearGradient id="stone" x1="110" y1="0" x2="190" y2="300"><stop stop-color="#d6cce0"/><stop offset=".5" stop-color="#61556e"/><stop offset="1" stop-color="#221c2b"/></linearGradient></defs><circle cx="150" cy="145" r="125" fill="#8b5cf6" opacity=".06"/><path d="M120 113c-30-50 58-63 47-111 62 51 11 71 28 99-3 25-51 39-75 12Z" fill="#8b5cf6"/><path d="M143 117c-21-35 30-44 26-77 30 35-3 54 10 68-5 20-25 24-36 9Z" fill="#c4b5fd"/><path d="m111 119 17 37h47l22-37Z" fill="url(#stone)"/><path d="M106 117h96v10h-96ZM126 153h53v10h-53Zm10 12 8 129h17l8-129Z" fill="url(#stone)"/><path d="m139 210-22 13-9 45-14 27 36 18 18-34 22-24-3-43-11-4-8 33-3-26Z" fill="url(#stone)"/><path d="m145 221 20 7m-22 4 20 7m-22 4 19 7" stroke="#d6cce0" opacity=".6" stroke-width="2"/></svg>`;
function splitHero(label,title,copy,art,cta){return `<section class="split-hero grid-bg"><div class="wrap split"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${copy}</p>${btns(cta)}</div><div class="sculpture">${art}</div></div></section>`}
function pricing(){return `${splitHero('Pricing','We quote a phase <strong>after discovery.</strong>','Software is not sold from a menu. After a short discovery, we scope a controlled phase around your outcome, platforms, integrations and risk.',scale,'Get a phase quote')}<section class="section" id="phases"><div class="wrap"><span class="eyebrow">Clear scope. Clear next steps.</span><h2>Core delivery <strong>phases.</strong></h2><p>Each line is a typical phase shape. The commercial quote comes after we understand what “done” means for your product.</p>${services.slice(0,5).map((s,i)=>`<details class="phase"><summary><div><h3>${s}</h3><small>${descriptions[i]}</small><small class="quote-label">Quoted after a short discovery</small></div><em>4–8 week phase</em></summary><p>We agree your priorities, map the key user journeys and define the technical approach. Your proposal includes specific deliverables, acceptance criteria, dependencies and a handover plan for ${s.toLowerCase()}.</p></details>`).join('')}</div></section><section class="section"><div class="wrap split"><div class="intro"><h2>The unit of work is <strong>a phase.</strong></h2><p>We price a delivery commitment with a clear outcome.</p></div><div class="hairline-grid">${[['Focused Build Phase','4–8 weeks','A defined product outcome, designed, engineered, tested and handed over.'],['Launch-Ready MVP','Quoted after discovery','The smallest credible version of the product that can reach real users.'],['Continuation Phase','Quoted after discovery','A second or later phase after the core workflow is already in production.'],['Specialist Support','Agreed engagement','Design, security, infrastructure or project management where the risk requires it.']].map(([t,l,p])=>`<div class="hairline-cell"><h3>${t}</h3><small>${l}</small><p>${p}</p></div>`).join('')}</div></div></section><section class="section tint"><div class="wrap split"><div class="intro"><h2>What the fee is <strong>paying for.</strong></h2><p>Exact scope changes by phase. Third-party fees and specialist work are included only when the proposal says so.</p></div><div><div class="hairline-grid">${['Discovery, scope and acceptance criteria','Product / UI design where scoped','Engineering across agreed platforms','Project management and status updates','QA, UAT support and release preparation','Documentation, handover and contracted warranty'].map(s=>`<div class="hairline-cell"><p>✓ &nbsp;${s}</p></div>`).join('')}</div><div class="tags">${services.slice(5).map(s=>`<button class="btn" data-contact>${s} ↗</button>`).join('')}</div></div></div></section><section class="section"><div class="wrap"><h2>What moves <strong>the quote.</strong></h2><div class="drivers">${[['Platforms','Web, mobile, or both change the workload.'],['Complexity','Roles, payments, workflows and admin systems add effort.'],['Integrations','External services add dependencies and risk.'],['Starting point','An approved design is a different starting point from an idea.']].map(([t,p])=>`<div class="driver"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="section dark"><div class="wrap"><div class="center-callout"><h2>Large products become a<br><strong>sequence of phases.</strong></h2><p>If the full product cannot fit one phase, we split it into deliverable outcomes. Each has its own scope, acceptance evidence and commercial terms.</p></div></div></section><section class="section tint"><div class="wrap faq-wrap"><h2>Pricing <strong>questions.</strong></h2>${faq(pricingFaq)}</div></section>`}
function about(){return `${splitHero('About Align Craft','Somebody has to <strong>own the outcome.</strong>','Align Craft brings product thinking, design and engineering together. One clear direction, from the first conversation to the final handover.',torch,'Start a project')}<section class="section tint"><div class="wrap split"><div class="intro"><h2>We get software into production<br><strong>with a clear plan.</strong></h2><p>Too many projects fall between handoffs: designer to developer, developer to infrastructure, until the founder becomes the project manager.</p><p><strong>Our approach connects those disciplines.</strong> A shared plan keeps decisions, delivery and the product outcome aligned.</p></div><div class="context dark"><span class="eyebrow">Our operating principle</span><h2>Built with intention.<br><strong class="accent">Built for production.</strong></h2><p>We work from the reality of your business: how customers pay, how teams operate and what the product needs to do when real people depend on it.</p></div></div></section><section class="section" id="standards"><div class="wrap"><span class="eyebrow">How we operate</span><h2>The standards behind <strong>the work.</strong></h2><div class="standards">${[['Clarity before code','Outcome, scope, price and ownership before the build starts.'],['Speed with quality','Momentum comes from clear decisions and a dependable foundation.'],['Visible scope changes','New work gets a written impact on price and timeline.'],['Production readiness','QA, release, credentials, documentation and known limitations.'],['Security & privacy','Access limited to what the work requires.'],['Handover you can run','You should have the knowledge and documentation to operate what ships.']].map(([t,p])=>`<div class="standard"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="section tint" id="team"><div class="wrap"><span class="eyebrow">Accountability by design</span><h2>Named owners for<br><strong>every engagement.</strong></h2><p>The roles your product needs, with responsibilities agreed before work begins.</p><div class="roles">${[['Product lead','Keeps the outcome, priorities and delivery plan connected.'],['Product designer','Turns user needs into clear journeys and considered interfaces.'],['Frontend engineer','Brings the experience to life across devices and screen sizes.'],['Backend engineer','Owns the systems, data and integrations behind the experience.'],['Delivery lead','Keeps communication clear, dependencies visible and the handover useful.']].map(([t,p],i)=>`<div class="role"><div class="role-number">0${i+1}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="section"><div class="wrap ledger"><h2>A closer look at <strong>Align Craft.</strong></h2>${[['Studio','Align Craft'],['Focus','Product strategy, design & engineering'],['Engagement model','Defined delivery phases'],['Collaboration','One shared plan and clear ownership'],['Handover','Source, documentation & knowledge transfer']].map(([k,v])=>`<div class="ledger-row"><span>${k}</span><span>${v}</span></div>`).join('')}</div></section>`}
const page=location.pathname.replace(/\/$/,'');
$('#app').innerHTML=header()+`<main>${page==='/pricing'?pricing():page==='/about'?about():home()}</main>`+footer()+`<dialog class="modal" id="contact-modal"><button class="close" aria-label="Close enquiry">×</button><span class="eyebrow">Let’s find the right next step</span><h2>Big idea?<br><strong>Let’s align.</strong></h2><p>Tell us a little about your project. Create an enquiry summary you can copy and share with the Align Craft team.</p><form id="enquiry"><label>Your name<input name="name" required placeholder="Your name" autocomplete="name"></label><label>Email address<input name="email" type="email" required placeholder="you@company.com" autocomplete="email"></label><label>What are you building?<textarea name="project" required placeholder="The idea, the problem, and where you are today…"></textarea></label><label>What kind of help do you need?<select name="service">${services.map(s=>`<option>${s}</option>`).join('')}</select></label><button class="btn primary" type="submit">Create enquiry summary ↗</button><p class="contact-note">This preview prepares your enquiry locally. It does not send your details.</p></form><div id="enquiry-result" hidden></div></dialog><dialog class="modal" id="detail-modal"><button class="close" aria-label="Close detail">×</button><div class="detail-content"></div></dialog>`;
document.querySelectorAll('.navgroup>button').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';document.querySelectorAll('.navgroup>button').forEach(x=>{x.setAttribute('aria-expanded','false');x.nextElementSibling.classList.remove('open')});b.setAttribute('aria-expanded',String(open));b.nextElementSibling.classList.toggle('open',open)}));
document.addEventListener('click',e=>{if(!e.target.closest('.navgroup'))document.querySelectorAll('.navgroup>button').forEach(x=>{x.setAttribute('aria-expanded','false');x.nextElementSibling.classList.remove('open')})});
$('.menu-toggle').addEventListener('click',()=>{const open=$('.nav').classList.toggle('mobile-open');$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').textContent=open?'×':'☰';$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>{$('.nav').classList.remove('mobile-open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').textContent='☰'}));
document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>$('#contact-modal').showModal()));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.dropdown.open').forEach(d=>d.classList.remove('open'));document.querySelectorAll('[aria-expanded=true]').forEach(b=>b.setAttribute('aria-expanded','false'));$('.nav').classList.remove('mobile-open');$('.menu-toggle').textContent='☰'}});
$('#enquiry').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target), summary=`Project enquiry — Align Craft\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nService: ${f.get('service')}\n\n${f.get('project')}`;const result=$('#enquiry-result');result.hidden=false;result.innerHTML='<h3>Your enquiry is ready.</h3><p>Copy this summary to share with the studio. Nothing has been sent yet.</p><textarea readonly aria-label="Your enquiry summary" style="width:100%;min-height:180px;padding:12px;border:1px solid #e6e4f0;border-radius:6px"></textarea><button class="btn primary" id="copy-enquiry">Copy enquiry ↗</button>';result.querySelector('textarea').value=summary;$('#copy-enquiry').onclick=async()=>{try{await navigator.clipboard.writeText(summary);$('#copy-enquiry').textContent='Copied ✓'}catch{result.querySelector('textarea').select();$('#copy-enquiry').textContent='Select and copy the summary'}};result.scrollIntoView({behavior:'smooth',block:'nearest'})});
document.querySelectorAll('[data-project]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const i=+a.dataset.project,p=projects[i];$('.detail-content').innerHTML=`<span class="eyebrow">Illustrative concept · ${p[1]}</span><h2>${p[0]}<strong class="accent">.</strong></h2>${mockup(p,i)}<p style="margin-top:25px">${p[2]} This original concept demonstrates a possible product direction rather than a commissioned client project.</p><h3>The design challenge</h3><p>Make the core workflow feel effortless. Establish a distinctive visual language, a clear information hierarchy and an experience that works across devices.</p><h3>Our approach</h3><p>Start with the primary user task, simplify the journey, and build a consistent system of reusable components. Carry that thinking through product design and engineering.</p><a class="btn primary" href="/pricing">Explore a similar phase ↗</a>`;$('#detail-modal').showModal()}));
const notes=[['Your first release doesn’t need every feature.','The first release should answer a specific question: can people use this product to solve the problem that matters most? Start by writing that problem in one sentence.','Separate the essential workflow from the features that make it more convenient. The essential workflow must work from beginning to end; everything else can be evaluated against the learning it creates.','Define what a successful first phase looks like before you estimate it. A smaller, coherent product gives you something useful to launch, test and improve.'],['A good handover starts before the first line of code.','A handover is easier when it is a habit throughout the project. Clear decisions, accessible source code and current setup instructions keep knowledge from becoming trapped in a chat history.','Agree who will own hosting accounts, third-party services and production credentials. Record dependencies and known limitations as they appear, rather than reconstructing them at the end.','Before launch, ask someone to follow the documentation. Their questions reveal the gaps while there is still time to close them.'],['How to turn a big idea into a useful first phase.','Begin with the outcome rather than the complete feature list. Who needs the product, what are they trying to do, and what is stopping them today?','Map the smallest complete journey that delivers value. Identify assumptions, external dependencies and the decisions that could change your scope. Use discovery to resolve the most consequential unknowns.','Give the first phase a clear finish: an observable outcome, agreed acceptance criteria and a practical handover. Use what you learn to shape the phase that follows.']];
document.querySelectorAll('[data-article]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const n=notes[+a.dataset.article];$('.detail-content').innerHTML=`<span class="eyebrow">The studio notebook · 3 min read</span><h2>${n[0]}</h2><div class="article-body">${n.slice(1).map(p=>`<p>${p}</p>`).join('')}</div>`;$('#detail-modal').showModal()}));
